from .akf_pinn.pinn.derivatives import trajectory_derivatives
from .akf_pinn.pinn.network import TrajectoryMLP


DT = torch.float64

@dataclass
class V2Config:
    seed: int = 0
    residual: str = "integral"
    scale: str = "normalized"
    init: str = "ls"
    stage: int = 2000
    colloc: str = "uniform"
    hidden_layers: int = 4
    hidden_width: int = 64
    adam_iterations: int = 20000
    adam_lr: float = 1e-3
    lbfgs_iterations: int = 10000
    lbfgs_chunk_iterations: int = 100
    lbfgs_max_eval_per_chunk: int = 125
    lbfgs_tolerance_grad: float = 1e-8
    lbfgs_tolerance_change: float = 1e-14
    physics_points: int = 4096
    convergence_relative_loss: float = 1e-6        # the controlled benchmark's V1 thresholds, unchanged
    convergence_relative_parameter: float = 1e-4
    convergence_gradient: float = 1e-6

def force_knots(d):
    """ZOH effort levels on [knot_i, knot_{i+1}) in nondimensional time; first level held back to t_obs[0]."""
    tf = d.force_t
    lev = d.generalized_input(tf, torch.ones((), dtype=DT, device=tf.device))
    t0 = d.t_obs[0]
    keep = tf > t0
    knots = torch.cat([t0.reshape(1), tf[keep]])
    first = d.generalized_input(t0.reshape(1), torch.ones((), dtype=DT, device=tf.device))
    levels = torch.cat([first, lev[keep]])
    return knots, levels

def cumulative_effort(knots, levels, t):
    """J(t) = int_{knots[0]}^t tau, exact for the ZOH effort."""
    ends = torch.cat([knots[1:], torch.full((1,), float("inf"), dtype=DT, device=knots.device)])
    seg = (torch.minimum(t[:, None], ends[None, :]) - knots[None, :]).clamp(min=0.0)
    return seg @ levels

def collocation(d, n, mode, knots, levels):
    t0, t1 = d.t_obs[0], d.t_obs[-1]
    uni = t0 + (torch.arange(n, dtype=DT, device=t0.device) + .5) * (t1 - t0) / n
    if mode == "uniform":
        return uni
    jumps = torch.abs(torch.diff(levels)) > 1e-3 * levels.abs().max()
    ev = knots[1:][jumps]
    ev = ev[(ev > t0) & (ev < t1)]
    if len(ev) == 0:
        return uni
    half = n // 2
    g = torch.Generator(device="cpu").manual_seed(12345)
    centers = ev[torch.arange(half) % len(ev)].cpu()
    offs = (torch.rand(half, generator=g, dtype=DT) * 2 - 1) * 0.03 * float(t1 - t0)
    dense = (centers + offs).clamp(float(t0), float(t1)).to(t0.device)
    return torch.sort(torch.cat([uni[::2], dense]))[0]

def run(d, cfg: V2Config, init: dict, callback=None) -> dict:
    """d: nondimensional InteractionData (common.normalize); init: shared integral-LS result in nondimensional units."""
    dev = d.t_obs.device
    if dev.type == "cuda":
        torch.cuda.synchronize(); torch.cuda.reset_peak_memory_stats()
    started = time.perf_counter()
    torch.manual_seed(cfg.seed)
    model = TrajectoryMLP(d.t_obs[0], d.t_obs[-1], d.q_obs[0], None, cfg.hidden_layers, cfg.hidden_width).to(device=dev, dtype=DT)
    I0, c0 = (1.0, 1.0) if cfg.init == "native" else (init["inertia"], init["damping"])
    raw = torch.nn.Parameter(torch.tensor([math.log(I0), math.log(c0)], device=dev, dtype=DT))
    net_params = list(model.parameters())
    params = net_params + [raw]
    knots, levels = force_knots(d)
    times = collocation(d, cfg.physics_points, cfg.colloc, knots, levels)
    tau = d.generalized_input(times, torch.ones((), dtype=DT, device=dev)).detach()
    J = cumulative_effort(knots, levels, times).detach()
    t0 = d.t_obs[:1]
    scale = (torch.sqrt(torch.mean((J if cfg.residual == "integral" else tau) ** 2)) if cfg.scale == "normalized"
             else torch.ones((), dtype=DT, device=dev))

    def params_phys():
        r = raw.clamp(-30, 30).exp()
        return r[0], r[1]

    def losses(physics=True):
        data = (model(d.t_obs) - d.q_obs).square().mean()
        ic = (model(t0) - d.q_obs[:1]).square().mean()
        if not physics:
            return {"total": data + ic, "data": data, "physics": torch.zeros((), dtype=DT, device=dev), "ic": ic}
        I, c = params_phys()
        q, v, a = trajectory_derivatives(model, times)
        if cfg.residual == "strong":
            res = I * a + c * v - tau
        else:
            _, v0, _ = trajectory_derivatives(model, t0)
            res = I * (v - v0) + c * (q - model(t0)) - J
        phys = (res / scale).square().mean()
        total = data + phys + ic
        if not bool(torch.isfinite(total)):
            raise FloatingPointError("non-finite PINN-V2 loss")
        return {"total": total, "data": data, "physics": phys, "ic": ic}

    hist = []

    def snapshot(step, phase):
        L = losses()
        g = torch.autograd.grad(L["total"], params)
        I, c = params_phys()
        row = {k: float(v.detach()) for k, v in L.items()}
        row.update(step=step, phase=phase, inertia=float(I), damping=float(c),
                   network_gradient=float(torch.sqrt(sum(x.square().sum() for x in g[:-1]))),
                   log_inertia_gradient=float(g[-1][0]), log_damping_gradient=float(g[-1][1]),
                   elapsed_s=time.perf_counter() - started)
        hist.append(row)
        if callback:
            callback(row)
        return row

    snapshot(0, "initialization")
    if cfg.stage:
        opt = torch.optim.Adam(net_params, lr=cfg.adam_lr)
        for s in range(1, cfg.stage + 1):
            opt.zero_grad(set_to_none=True); losses(physics=False)["total"].backward(); opt.step()
        snapshot(cfg.stage, "stage_data_only")
    opt = torch.optim.Adam(params, lr=cfg.adam_lr)
    for s in range(1, cfg.adam_iterations + 1):
        opt.zero_grad(set_to_none=True); losses()["total"].backward(); opt.step()
        if s % 500 == 0 or s in (100, 1000):
            snapshot(cfg.stage + s, "adam")
    prev = snapshot(cfg.stage + cfg.adam_iterations, "pre_lbfgs")
    rel_loss = rel_I = rel_c = math.inf
    n_it = n_eval = 0
    stopped_by_rule = False
    if cfg.lbfgs_iterations:
        opt = torch.optim.LBFGS(params, max_iter=min(cfg.lbfgs_chunk_iterations, cfg.lbfgs_iterations), max_eval=cfg.lbfgs_max_eval_per_chunk,
                                tolerance_grad=cfg.lbfgs_tolerance_grad, tolerance_change=cfg.lbfgs_tolerance_change, line_search_fn="strong_wolfe")

        def closure():
            nonlocal n_eval
            n_eval += 1
            opt.zero_grad(set_to_none=True)
            v = losses()["total"]; v.backward()
            return v

        while n_it < cfg.lbfgs_iterations:
            opt.param_groups[0]["max_iter"] = min(cfg.lbfgs_chunk_iterations, cfg.lbfgs_iterations - n_it)
            opt.step(closure)
            tot = int(opt.state[params[0]]["n_iter"])
            if tot <= n_it:
                break
            n_it = tot
            cur = snapshot(cfg.stage + cfg.adam_iterations + n_it, "lbfgs")
            rel_loss = abs(cur["total"] - prev["total"]) / max(abs(prev["total"]), 1e-300)
            rel_I = abs(cur["inertia"] / prev["inertia"] - 1); rel_c = abs(cur["damping"] / prev["damping"] - 1)
            gmax = max(cur["network_gradient"], abs(cur["log_inertia_gradient"]), abs(cur["log_damping_gradient"]))
            prev = cur
            if rel_loss <= cfg.convergence_relative_loss and max(rel_I, rel_c) <= cfg.convergence_relative_parameter and gmax <= cfg.convergence_gradient:
                stopped_by_rule = True
                break
    fin = snapshot(cfg.stage + cfg.adam_iterations + n_it, "final")
    gmax = max(fin["network_gradient"], abs(fin["log_inertia_gradient"]), abs(fin["log_damping_gradient"]))
    pgrad = max(abs(fin["log_inertia_gradient"]), abs(fin["log_damping_gradient"]))
    stable_loss = rel_loss <= cfg.convergence_relative_loss
    stable_par = max(rel_I, rel_c) <= cfg.convergence_relative_parameter
    v1rule = ("converged" if stable_loss and stable_par and gmax <= cfg.convergence_gradient
              else "probably converged" if stable_par and pgrad <= cfg.convergence_gradient else "not converged")
    strict = bool(rel_loss <= 1e-10 and max(rel_I, rel_c) <= 1e-5 and max(fin["network_gradient"], pgrad) <= 1e-8)
    # diagnostic assessment (not the frozen rule): parameters and both losses stationary over the last 2000 L-BFGS
    # iterations, physical gradient small, finite; plus ODE consistency of the final network on a dense grid.
    lb = [h for h in hist if h["phase"] == "lbfgs"]
    tail = [h for h in lb if h["step"] >= (lb[-1]["step"] - 2000 if lb else 0)]
    par_range = max((np.ptp([h[k] for h in tail]) / np.mean([h[k] for h in tail]) for k in ("inertia", "damping")), default=math.inf) if len(tail) > 1 else math.inf
    loss_range = {k: (np.ptp([h[k] for h in tail]) / max(np.mean([h[k] for h in tail]), 1e-300)) if len(tail) > 1 else math.inf for k in ("data", "physics")}
    tg = d.t_obs[0] + (torch.arange(8192, dtype=DT, device=dev) + .5) / 8192 * (d.t_obs[-1] - d.t_obs[0])
    q, v, _ = trajectory_derivatives(model, tg, create_graph=False)
    _, v0, _ = trajectory_derivatives(model, t0, create_graph=False)
    I, c = params_phys()
    Jg = cumulative_effort(knots, levels, tg)
    ode_rel = float(torch.sqrt(torch.mean((I * (v - v0) + c * (q - model(t0)) - Jg) ** 2)) / torch.sqrt(torch.mean(Jg ** 2)))
    diag = dict(parameter_rel_range_last2000=float(par_range), data_loss_rel_range_last2000=float(loss_range["data"]),
                physics_loss_rel_range_last2000=float(loss_range["physics"]), physical_gradient=pgrad,
                ode_consistency_rel_rms=ode_rel, finite=bool(np.isfinite([fin["total"], fin["inertia"], fin["damping"]]).all()))
    diag["converged"] = bool(diag["finite"] and par_range <= 1e-4 and max(loss_range.values()) <= 1e-3 and pgrad <= 1e-5)
    if dev.type == "cuda":
        torch.cuda.synchronize()
    return dict(inertia=fin["inertia"], damping=fin["damping"], q_hat=model(d.t_obs).detach().cpu().tolist(),
                runtime_s=time.perf_counter() - started, convergence=v1rule,
                diagnostics=dict(config=asdict(cfg), init=dict(inertia=I0, damping=c0), history=hist, final=fin,
                                 relative_loss_change=rel_loss, relative_I_change=rel_I, relative_c_change=rel_c,
                                 lbfgs_iterations=n_it, lbfgs_evaluations=n_eval, stopped_by_v1_rule=stopped_by_rule,
                                 strict_original_convergence=strict, diagnostic_convergence=diag,
                                 peak_gpu_memory_mb=torch.cuda.max_memory_allocated() / 2 ** 20 if dev.type == "cuda" else None,
                                 state_dict={k: v.detach().cpu().tolist() for k, v in model.state_dict().items()}))
